export type TokenName = keyof typeof GLOBAL_TOKENS;
export type TokenGroup = (typeof GLOBAL_TOKENS)[TokenName]["group"];
export type RuntimeTokenName = {
  [Name in TokenName]: (typeof GLOBAL_TOKENS)[Name]["kind"] extends "runtime" ? Name : never
}[TokenName];

export const TOKEN_NAMES = Object.keys(GLOBAL_TOKENS) as TokenName[];
export const RUNTIME_TOKEN_NAMES = TOKEN_NAMES.filter(
  (name): name is RuntimeTokenName => GLOBAL_TOKENS[name].kind === "runtime",
);
